import json, pathlib
p = pathlib.Path("tests/project_prompt/script.json")
raw = p.read_text(encoding="utf-8")
d = json.loads(raw)
indent = 2 if raw.startswith('{\n  "') else 4
ascii_ = "\\u" in raw
gone = {"petg-restated", "petg-restated-after-read", "omitted-replay", "issue-fix-after-read",
        "loaded-vs-configured-after-read", "first-person-after-read", "reply-in-german-after-read"}
convs = []
for c in d["conversations"]:
    if c["name"] == "omitted":
        continue
    steps = []
    for s in c["steps"]:
        recs = [r.get("record") for r in s.get("replies", []) if r.get("record")]
        if recs and all(r in gone for r in recs):
            continue  # the "like I said" step
        replies = []
        for r in s.get("replies", []):
            if r.get("record") in gone:
                continue
            if r.get("record") in {"issue-fix", "loaded-vs-configured", "first-person", "reply-in-german"} and "call" in r:
                replies.append({"record": r["record"]})  # the scripted read only led to the dropped variant
            else:
                replies.append(r)
        s = dict(s); s["replies"] = replies; steps.append(s)
    c = dict(c); c["steps"] = steps; convs.append(c)
d["conversations"] = convs
out = json.dumps(d, indent=indent, ensure_ascii=ascii_) + ("\n" if raw.endswith("\n") else "")
p.write_text(out, encoding="utf-8")
for c in d["conversations"]:
    for s in c["steps"]:
        print(c["name"], "|", json.dumps(s.get("say"))[:50], "| records:", [r.get("record") for r in s["replies"] if r.get("record")], "| calls:", [r.get("call") for r in s["replies"] if r.get("call")])
EOF
