import json, pathlib
p = pathlib.Path("tests/project_prompt/requests.json")
raw = p.read_text(encoding="utf-8")
d = json.loads(raw)
gone = {"petg-restated", "petg-restated-after-read", "omitted-replay", "issue-fix-after-read",
        "loaded-vs-configured-after-read", "first-person-after-read", "reply-in-german-after-read"}
before = len(d["cases"]); before_items = len(d["settingItems"])
for g in gone: del d["cases"][g]
# prune setting items no remaining answer references, and remap indices
used = set()
for case in d["cases"].values():
    for a in case["answers"]:
        if a.get("settingItems"):
            out = json.loads(a["output"])
            for f in ("items", "unknownKeys"):
                used.update(out["result"].get(f, []))
keep = sorted(used)
remap = {old: new for new, old in enumerate(keep)}
for case in d["cases"].values():
    for a in case["answers"]:
        if a.get("settingItems"):
            out = json.loads(a["output"])
            for f in ("items", "unknownKeys"):
                if f in out["result"]:
                    out["result"][f] = [remap[i] for i in out["result"][f]]
            a["output"] = json.dumps(out, separators=(",", ":"), sort_keys=True, ensure_ascii=False)
d["settingItems"] = [d["settingItems"][i] for i in keep]
# formatting: match the original (compact vs indented, ascii)
indent = None if raw[:2] == '{"' else 2
out = json.dumps(d, indent=indent, separators=None if indent else (",", ":"), sort_keys=True, ensure_ascii="\\u" in raw) + ("\n" if raw.endswith("\n") else "")
p.write_text(out, encoding="utf-8")
print(f"cases {before} -> {len(d['cases'])}; settingItems {before_items} -> {len(d['settingItems'])}; bytes {len(raw)} -> {len(out)}")
print(sorted(d["cases"]))
EOF

