import ast, re, pathlib, json
drop = {"OmittedReplay", "IssueFixAfterRead", "LoadedVsConfiguredAfterRead", "FirstPersonAfterRead", "ReplyInGermanAfterRead"}
gone = {"omitted-replay", "issue-fix-after-read", "loaded-vs-configured-after-read", "first-person-after-read", "reply-in-german-after-read"}
# runner
p = pathlib.Path("tests/project_prompt/run_prompt_tests.py"); src = p.read_text(encoding="utf-8")
tree = ast.parse(src); lines = src.split("\n")
ranges = sorted(((n.lineno, n.end_lineno) for n in tree.body if isinstance(n, ast.ClassDef) and n.name in drop), reverse=True)
assert len(ranges) == len(drop)
for start, end in ranges:
    e = end
    while e < len(lines) and lines[e].strip() == "": e += 1
    del lines[start - 1:e]; lines.insert(start - 1, ""); lines.insert(start - 1, "")
src = "\n".join(lines)
for name in drop: src = re.sub(r"\b" + name + r",\s*", "", src)
old_comment = re.search(r"# The same five points one step later.*?originals reach the reply on their own\.\n", src, re.S)
if old_comment: src = src.replace(old_comment.group(0), "")
src = re.sub(r"\n{4,}", "\n\n\n", src)
assert "RUN_BUDGET = 72" in src and "3 each for 24 cases" in src
src = src.replace("RUN_BUDGET = 72", "RUN_BUDGET = 54").replace("3 each for 24 cases", "3 each for 18 cases")
ast.parse(src); p.write_text(src, encoding="utf-8")
print(re.search(r"CASES = \{.*?\)\}", src, re.S).group(0))
# script.json (indent 1, order kept)
p = pathlib.Path("tests/project_prompt/script.json"); d = json.loads(p.read_text(encoding="utf-8"))
convs = []
for c in d["conversations"]:
    if c["name"] == "omitted": continue
    steps = []
    for s in c["steps"]:
        replies = []
        for r in s.get("replies", []):
            if r.get("record") in gone: continue
            if r.get("record") in {"issue-fix", "loaded-vs-configured", "first-person", "reply-in-german"} and "call" in r:
                replies.append({"record": r["record"]})
            else: replies.append(r)
        s = dict(s); s["replies"] = replies; steps.append(s)
    c = dict(c); c["steps"] = steps; convs.append(c)
d["conversations"] = convs
p.write_text(json.dumps(d, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
# requests.json (indent 1, sorted)
p = pathlib.Path("tests/project_prompt/requests.json"); d = json.loads(p.read_text(encoding="utf-8"))
for g in gone: del d["cases"][g]
used = set()
for case in d["cases"].values():
    for a in case["answers"]:
        if a.get("settingItems"):
            out = json.loads(a["output"])
            for f in ("items", "unknownKeys"): used.update(out["result"].get(f, []))
keep = sorted(used); remap = {o: n for n, o in enumerate(keep)}
if len(keep) != len(d["settingItems"]):
    for case in d["cases"].values():
        for a in case["answers"]:
            if a.get("settingItems"):
                out = json.loads(a["output"])
                for f in ("items", "unknownKeys"):
                    if f in out["result"]: out["result"][f] = [remap[i] for i in out["result"][f]]
                a["output"] = json.dumps(out, separators=(",", ":"), sort_keys=True, ensure_ascii=False)
    d["settingItems"] = [d["settingItems"][i] for i in keep]
p.write_text(json.dumps(d, indent=1, sort_keys=True, ensure_ascii=False) + "\n", encoding="utf-8")
print("cases:", len(d["cases"]), "settingItems:", len(keep), "of", len(d["settingItems"]))
EOF
